import { useEffect, useState } from "react";

function Marks() {
  const [students, setStudents] = useState([]);
  const [marks, setMarks] = useState({}); // { studentId: {subject: marks} }
  const [subject, setSubject] = useState(""); // current subject input
  const [subjectsList, setSubjectsList] = useState([]); // list of subjects added

  useEffect(() => {
    setStudents(JSON.parse(localStorage.getItem("students")) || []);
  }, []);

  // Add subject dynamically
  const addSubject = () => {
    if (subject && !subjectsList.includes(subject)) {
      setSubjectsList([...subjectsList, subject]);
      setSubject("");
    }
  };

  // Handle marks input
  const handleMarksChange = (studentId, subj, value) => {
    setMarks({
      ...marks,
      [studentId]: {
        ...marks[studentId],
        [subj]: value
      }
    });
  };

  // Save marks to LocalStorage
  const saveMarks = () => {
    const storedMarks = JSON.parse(localStorage.getItem("marks")) || {};
    students.forEach(student => {
      storedMarks[student.id] = marks[student.id] || {};
    });
    localStorage.setItem("marks", JSON.stringify(storedMarks));
    alert("Marks saved successfully");
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Enter Student Marks</h2>

      <div style={{ marginBottom: "20px" }}>
        <input
          placeholder="Enter subject"
          value={subject}
          onChange={e => setSubject(e.target.value)}
        />
        <button onClick={addSubject}>Add Subject</button>
      </div>

      {subjectsList.length === 0 && <p>No subjects added</p>}

      {students.map(student => (
        <div key={student.id} style={{ border: "1px solid #ccc", padding: "10px", marginBottom: "10px" }}>
          <b>{student.name}</b> (Roll: {student.roll})
          <br /><br />

          {subjectsList.map(subj => (
            <div key={subj} style={{ marginBottom: "5px" }}>
              <label>{subj}: </label>
              <input
                type="number"
                placeholder="Marks"
                value={(marks[student.id] && marks[student.id][subj]) || ""}
                onChange={e => handleMarksChange(student.id, subj, e.target.value)}
              />
            </div>
          ))}
        </div>
      ))}

      <button onClick={saveMarks}>Save All Marks</button>
    </div>
  );
}

export default Marks;
